const caseMap: Map<string, CaseRef[]> = new Map();
for (const c of cases) {
  const list = caseMap.get(c.strategyId) ?? [];
  list.push(c);
  caseMap.set(c.strategyId, list);
}

export function getCasesByStrategy(strategyId: string): CaseRef[] {
  return caseMap.get(strategyId) ?? [];
}
